use std::fs;
use std::path::Path;

// Memo: Always prepend this header so I don't accidentally edit the generated files.
const HEADER: &str = "// @generated\n// This file is auto-generated by build.rs. DO NOT EDIT.\n\n";

fn main() {
    generate_jsonb_functions();
    generate_json_tree_function();
}

fn generate_jsonb_functions() {
    // Mapping out the source files to their generated destination paths.
    let files = vec![
        ("src/dsl/function/json_extract.rs", "src/dsl/function/jsonb_extract.rs"),
        ("src/dsl/function/json_group_array.rs", "src/dsl/function/jsonb_group_array.rs"),
        ("src/dsl/function/json_object.rs", "src/dsl/function/jsonb_object.rs"),
    ];

    for (src_path, dst_path) in files {
        // Core trick: Explicitly tell Cargo to only rerun this build script if these specific
        // json_xxx.rs files are modified. Saves us unnecessary compilation time.
        println!("cargo:rerun-if-changed={}", src_path);

        let src = Path::new(src_path);
        let dst = Path::new(dst_path);

        if src.exists() {
            let content = fs::read_to_string(src).expect("Failed to read source file");

            // Performing a dead-simple text replacement strategy:
            // 1. "Json" -> "Jsonb" (Catches struct names like JsonExtract -> JsonbExtract,
            // and enum variants like ExtFunction::JsonObject -> JsonbObject).
            // 2. "json_" -> "jsonb_" (Catches internal comments, snake_case macro/function names, etc.).
            let new_content = content
                .replace("Json", "Jsonb")
                .replace("json_", "jsonb_")
                .replace("type Output = String;", "type Output = Vec<u8>;");

            let final_content = format!("{}{}", HEADER, new_content);

            fs::write(dst, final_content).expect("Failed to write generated file");
        }
    }
}

fn generate_json_tree_function() {
    let src_path = "src/dsl/function/from/json_each.rs";
    let dst_path = "src/dsl/function/from/json_tree.rs";

    // Memo: Apply the same rerun tracking rule here.
    println!("cargo:rerun-if-changed={}", src_path);

    let src = Path::new(src_path);
    let dst = Path::new(dst_path);

    if src.exists() {
        let content = fs::read_to_string(src).expect("Failed to read source file");

        // Memo: json_each and json_tree have identical signatures in SQLite.
        // Need to precisely cover the struct name (JsonEach), module/table name (json_each),
        // and the static default instance (JSON_EACH_DEFAULT).
        let new_content = content
            .replace("JsonEach", "JsonTree")
            .replace("json_each", "json_tree")
            .replace("JSON_EACH", "JSON_TREE");

        let final_content = format!("{}{}", HEADER, new_content);
        fs::write(dst, final_content).expect("Failed to write generated json_tree file");
    }
}
